mapper.sql:
WHERE r.user_id=#{userId}
          AND r.deleted_at IS NULL
        AND r.name ILIKE '%' || #{q.keyword} || '%'
        AND r.status=#{q.status}AND (r.archived_at IS NOT NULL)=#{q.archived}
        AND r.start_date >= #{q.startFrom}
        AND r.start_date <= #{q.startTo}
        AND r.status<>'COMPLETED'
          AND (r.start_date IS NULL OR r.start_date <= #{q.today})
        AND r.status<>'COMPLETED'
          AND r.start_date > #{q.today}

mapper.select:
SELECT 
        FROM goal r
        WHERE r.user_id=#{userId}
          AND r.id=#{id}
          AND r.deleted_at IS NULL

SELECT 
        FROM goal r 
        ORDER BY r.id DESC
        LIMIT #{q.size}
        OFFSET #{q.offset}
